uint16_t ap_num = 0;
esp_wifi_scan_get_ap_num(&ap_num);
wifi_ap_record_t *ap_records = (wifi_ap_record_t *)malloc(ap_num * sizeof(wifi_ap_record_t));
esp_wifi_scan_get_ap_records(&ap_num, ap_records);

uint16_t ap_num = 0;
auto scan_error = esp_wifi_scan_get_ap_num(&ap_num);
std::vector<wifi_ap_record_t> records(ap_num);
if (scan_error == ESP_OK && ap_num != 0) {
    scan_error = esp_wifi_scan_get_ap_records(&ap_num, records.data());
}
if (scan_error != ESP_OK) {
    ESP_LOGW(TAG, "SCAN_READ_FAILED code=%d", int(scan_error));
    esp_wifi_clear_ap_list();
    esp_timer_start_once(timer_handle_, scan_current_interval_microseconds_);
    UpdateScanInterval();
    return;
}
records.resize(ap_num);
connect_queue_.clear();

// A hidden SSID need not appear in scan results. Try at most three
// saved credentials, with no stale channel or invented BSSID pin.
for (auto index : claw4::DirectCandidates(ssid_list, remember_bssid_ != 0)) {
    WifiApRecord record{};
    record.ssid = ssid_list[index].ssid;
    record.password = ssid_list[index].password;
    record.direct = true;
    connect_queue_.push_back(record);
}
if (!connect_queue_.empty()) {
    ESP_LOGI(TAG, "SAVED_DIRECT_FALLBACK candidates=%u", unsigned(connect_queue_.size()));
    StartConnect();
    return;
}
ESP_LOGI(TAG, "No AP found, next scan in %d seconds", scan_current_interval_microseconds_ / 1000 / 1000);

// One driver attempt per fallback candidate; retain ordinary visible-AP
// retry behavior. Failed candidates progress to the next, then back off.
reconnect_count_ = ap_record.direct ? MAX_RECONNECT_COUNT : 0;
const auto connect_error = esp_wifi_connect();
if (ap_record.direct && connect_error != ESP_OK) {
    ESP_LOGW(TAG, "SAVED_DIRECT_START_FAILED code=%d", int(connect_error));
    if (!connect_queue_.empty()) {
        StartConnect(); // Bounded by the three-entry fallback queue.
    } else {
        esp_timer_start_once(timer_handle_, scan_current_interval_microseconds_);
        UpdateScanInterval();
    }
    return;
}
ESP_ERROR_CHECK(connect_error);
